mapper.select:
select
R1.resource_id, R1.name, R1.difficulty, R1.create_user_id, count(R3.id) as lesson_count,
count(distinct L1.user_id) as learning_count, R2.name as direction_name, count(L2.id) as report_count
from oj_course R1
left join oj_course_category R2 on R1.category_id = R2.resource_id
left join oj_course_lesson R3 on R1.resource_id = R3.course_id
left join oj_lesson_record L1 on R1.resource_id = L1.course_id
left join oj_note L2 on R2.resource_id = L2.business_id and L2.note_type = #{report_code} and L2.business_type = #{lesson_code}


        and R1.category_id = #{category_id}


        and R1.difficulty = #{difficulty}



        and R1.name like #{pattern}


group by R1.resource_id;

select
       R1.resource_id, R1.course_id, R1.name, R1.type, R1.difficulty, count(distinct L1.user_id) as learning_count,
       count(L2.resource_id) as report_count, 0 as finishPractice_count
from oj_course_lesson R1
left join oj_lesson_record L1 on R1.resource_id = L1.lesson_id
left join oj_note L2 on R1.resource_id = L2.business_id and L2.note_type = #{report_code} and L2.business_type = #{lesson_code}
left join oj_lesson_paper_evaluate L3 on R1.resource_id = L3.lesson_id

    R1.course_id = #{course_id}


        and R1.name like #{pattern}


        and R1.type = #{type}


group by R1.resource_id;

select L1.user_id as resource_id, count(L1.lesson_id) as lesson_record_count, count(L2.id) as finish_report_count, avg(L3.score) as report_average from oj_lesson_record L1 left join oj_note L2 on L2.note_type = #{report_code} and L1.user_id = L2.user_id left join oj_note_evaluate L3 on L2.resource_id = L3.note_id
L1.user_id in #{user_id}
group by L1.user_id;

select user_id, count(*) as `count` from oj_lesson_record
where user_id in #{user_id}
group by user_id order by `count` desc limit 5;

select T1.user_id, count(T2.resource_id) as `count`
from oj_note T1 left join oj_note_evaluate T2 on T1.resource_id = T2.note_id
where T1.note_type = #{report_code} and T2.passed = 1 and T1.user_id in #{user_id}
group by T1.user_id order by `count` desc;

select date_format(create_time, '%Y-%m-%d') as `date`, count(*) as `count`
from oj_lesson_record
where user_id = #{user_id} and date_format(create_time, '%Y-%m-%d') in #{date}
group by date_format(create_time, '%Y-%m-%d');

select
date_format(create_time, '%Y-%m-%d') as `date`, count(T2.score) as `count`, sum(T2.score) as score
from oj_note T1 left join oj_note_evaluate T2 on T1.resource_id = T2.note_id
where T1.note_type = #{report_code} and T2.passed = 1 and T1.user_id = #{user_id}
and date_format(create_time, '%Y-%m-%d') in #{date}
group by date_format(create_time, '%Y-%m-%d');
